import * as T from './vendor/three.module.js';
import {SHOALS} from './config.js';
import {Materials} from './models/ModelUtils.js';
import {createBoatModel,BOAT_ANCHORS} from './models/BoatModel.js';
import {CoastModel} from './models/CoastModel.js';
import {AssetManager} from './models/AssetManager.js';
import {OceanRenderer} from './ocean/OceanRenderer.js';
import {oceanPhysics,BoatFloat,createSurfaceSample} from './ocean/OceanPhysics.js';
import {skyVertex,skyFragment} from './ocean/AtmosphereShader.js';
export class World{
constructor(root){this.scene=new T.Scene();this.scene.fog=new T.FogExp2(0x8aabb4,.0017);this.renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});this.renderer.setSize(innerWidth,innerHeight);this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.15;this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;root.append(this.renderer.domElement);this.camera=new T.PerspectiveCamera(53,innerWidth/innerHeight,.1,3000);this.camera.position.set(13,10,23);this.target=new T.Vector3();this.camTarget=new T.Vector3();this.offset=new T.Vector3();this.sun=new T.DirectionalLight(0xffe5b7,2.3);this.sun.position.set(-80,55,-120);this.sun.castShadow=true;this.sun.shadow.mapSize.set(1024,1024);this.sun.shadow.camera.left=-60;this.sun.shadow.camera.right=60;this.sun.shadow.camera.top=60;this.sun.shadow.camera.bottom=-60;this.scene.add(this.sun,this.sun.target);this.ambient=new T.HemisphereLight(0xb2d1df,0x414c41,2);this.scene.add(this.ambient);
this.sunDirection=new T.Vector3(-80,55,-120).normalize();this.uniforms={time:{value:0},light:{value:1},storm:{value:0},sunDirection:{value:this.sunDirection}};this.ocean=new OceanRenderer(this.scene,this.renderer,oceanPhysics);this.float=new BoatFloat(oceanPhysics);this.surfaceSample=createSurfaceSample();this.rodTip=new T.Vector3();this.sky=new T.Mesh(new T.SphereGeometry(1300,40,24),new T.ShaderMaterial({uniforms:this.uniforms,vertexShader:skyVertex,fragmentShader:skyFragment,side:T.BackSide,depthWrite:false}));this.scene.add(this.sky);
this.assets=new AssetManager();this.modelMaterials=new Materials({anisotropy:this.renderer.capabilities.getMaxAnisotropy()});this.mat={wood:new T.MeshStandardMaterial({color:0x65503a,roughness:.9}),trim:new T.MeshStandardMaterial({color:0x284f50,roughness:.85}),metal:new T.MeshStandardMaterial({color:0x535b5b,metalness:.7,roughness:.45}),cream:new T.MeshStandardMaterial({color:0xc8c0a0,roughness:.85}),roof:new T.MeshStandardMaterial({color:0x6d5344,roughness:.95}),land:new T.MeshStandardMaterial({color:0x566553,roughness:1}),rock:new T.MeshStandardMaterial({color:0x69736b,roughness:1})};this.makeCoast();this.boat=this.makeBoat();this.scene.add(this.boat);this.bobber=new T.Mesh(new T.SphereGeometry(.15,10,8),new T.MeshStandardMaterial({color:0xe3884c}));this.scene.add(this.bobber);this.line=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(),new T.Vector3()]),new T.LineBasicMaterial({color:0xc8d7c8,transparent:true,opacity:.8}));this.scene.add(this.line);this.bobber.visible=this.line.visible=false;
this.fishGroup=new T.Group();const fishMat=new T.MeshStandardMaterial({color:0x96b6b3,metalness:.4,roughness:.4});for(const shoal of SHOALS){for(let j=0;j<6;j++){const f=new T.Mesh(new T.SphereGeometry(.35,8,5),fishMat);f.scale.set(.4,.5,1.8);f.position.set(shoal.x+Math.sin(j)*3,-.7,shoal.z+Math.cos(j)*3);f.userData={x:shoal.x,z:shoal.z,phase:j};this.fishGroup.add(f);}}this.scene.add(this.fishGroup);
this.shark=new T.Group();const sm=new T.MeshStandardMaterial({color:0x34474e,roughness:.5});const body=new T.Mesh(new T.SphereGeometry(1,14,10),sm);body.scale.set(.65,.55,2.5);body.position.y=-.45;this.shark.add(body);const finGeo=new T.BufferGeometry();finGeo.setAttribute('position',new T.Float32BufferAttribute([0,0,1,0,1.5,-.2,0,0,-1],3));finGeo.computeVertexNormals();const fin=new T.Mesh(finGeo,new T.MeshStandardMaterial({color:0x34474e,side:T.DoubleSide}));this.shark.add(fin);this.scene.add(this.shark);this.shark.visible=false;
const rainPos=new Float32Array(1200*3);for(let i=0;i<rainPos.length;i+=3){rainPos[i]=(Math.random()-.5)*90;rainPos[i+1]=Math.random()*45;rainPos[i+2]=(Math.random()-.5)*90;}this.rain=new T.Points(new T.BufferGeometry().setAttribute('position',new T.BufferAttribute(rainPos,3)),new T.PointsMaterial({color:0xb4cbd0,size:.1,transparent:true,opacity:.5}));this.scene.add(this.rain);this.onResize=()=>{this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix();this.renderer.setSize(innerWidth,innerHeight);this.ocean.resize();};addEventListener('resize',this.onResize);}
box(w,h,d,mat,x=0,y=0,z=0,parent=this.scene){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
makeBoat(){this.boatModel=createBoatModel(this.modelMaterials);const g=this.boatModel.group;const person=new T.Group();this.box(.65,.85,.4,new T.MeshStandardMaterial({color:0x7f6044}),0,1.65,0,person);const head=new T.Mesh(new T.SphereGeometry(.25,12,8),new T.MeshStandardMaterial({color:0xbfa17b}));head.position.y=2.3;person.add(head);const hat=new T.Mesh(new T.CylinderGeometry(.45,.43,.1,16),this.mat.cream);hat.position.y=2.49;person.add(hat);for(const x of [-.2,.2])this.box(.22,.65,.25,this.mat.trim,x,1.05,0,person);g.add(person);this.rod=new T.Group();const pole=new T.Mesh(new T.CylinderGeometry(.018,.04,4,7),this.mat.wood);pole.rotation.z=-.55;pole.position.set(.7,2.5,-1);this.rod.add(pole);g.add(this.rod);this.spearMesh=this.box(.05,.05,4,this.mat.metal,-.8,1.8,-1,g);this.spearMesh.visible=false;this.upgradeBox=this.box(.85,.5,.65,this.mat.trim,-.5,1,1.6,g);this.upgradeBox.visible=false;return g;}
makeCoast(){this.coast=new CoastModel(this.scene,this.modelMaterials);this.homeRoof=this.coast.village.homeRoof;}
ripple(x,z,size=1){this.ocean.ripple(x,z,size);}
quality(q){this.renderer.setPixelRatio(Math.min(devicePixelRatio,q==='Alta'?2:q==='Média'?1.5:1));this.renderer.shadowMap.enabled=q!=='Baixa';this.ocean.setQuality(q);this.modelMaterials.quality(q);this.coast.setQuality(q);}
dispose(){removeEventListener('resize',this.onResize);this.ocean.dispose();this.coast.dispose();this.assets.dispose();const geometries=new Set(),materials=new Set();this.scene.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)for(const m of (Array.isArray(o.material)?o.material:[o.material]))materials.add(m);});for(const g of geometries)g.dispose();const owned=new Set(this.modelMaterials.materials.values());for(const m of materials)if(!owned.has(m))m.dispose();this.modelMaterials.dispose();this.renderer.dispose();this.renderer.domElement.remove();}
update(dt,t,b,s,fish,shark,orbit,storm,spear){const light=.25+.75*Math.max(0,Math.sin((s.time-6)/12*Math.PI));this.uniforms.time.value=t;this.uniforms.light.value=light;this.uniforms.storm.value=storm;this.sun.intensity=light*2.3;this.ambient.intensity=.6+light*1.4;this.scene.fog.color.setRGB(.43*light,.55*light,.59*light);this.sun.position.set(b.x-80,55,b.z-120);this.sun.target.position.set(b.x,0,b.z);this.ocean.update(dt,t,b,light,storm,this.sunDirection,this.scene.fog.color);const pose=this.float.update(b.x,b.z,b.angle,t,dt);this.boat.position.set(b.x,pose.y,b.z);this.boat.rotation.set(pose.pitch,b.angle,pose.roll,'YXZ');this.rod.rotation.x=fish.state==='reeling'?-.15+Math.sin(t*9)*.08:0;this.spearMesh.visible=spear;this.spearMesh.position.z=-1-(shark.cooldown>0?Math.sin(shark.cooldown*4)*1.5:0);this.upgradeBox.visible=s.upgrades.hold>0;if(this.homeRoof)this.homeRoof.material.color.setHex([0x6d5344,0x885c46,0x9a6247,0xb07851][s.upgrades.home]);this.boatModel.hullMaterial.color.setHex(s.upgrades.hull>0?0xc7e2cd:0xffffff);this.boatModel.update(t,b.enginePower||0);
const angle=b.angle+orbit;this.offset.set(Math.sin(angle)*23,8,Math.cos(angle)*23);this.camTarget.set(b.x+this.offset.x,this.offset.y+pose.y*.35,b.z+this.offset.z);this.camera.position.lerp(this.camTarget,1-Math.exp(-dt*2.8));this.target.set(b.x-Math.sin(angle)*6,1+pose.y*.35,b.z-Math.cos(angle)*6);this.camera.lookAt(this.target);this.sky.position.copy(this.camera.position);this.bobber.visible=this.line.visible=fish.state!=='idle';if(this.bobber.visible){oceanPhysics.sampleOceanSurface(b.x+6,b.z-7,t,this.surfaceSample);this.bobber.position.set(b.x+6,this.surfaceSample.height+.12,b.z-7);this.boat.updateMatrixWorld();this.rodTip.set(...BOAT_ANCHORS.rodTip).applyMatrix4(this.boat.matrixWorld);const p=this.line.geometry.attributes.position;p.setXYZ(0,this.rodTip.x,this.rodTip.y,this.rodTip.z);p.setXYZ(1,this.bobber.position.x,this.bobber.position.y,this.bobber.position.z);p.needsUpdate=true;this.line.geometry.computeBoundingSphere();if(fish.state==='bite'&&Math.sin(t*15)>.9)this.ripple(b.x+6,b.z-7,.4);}
for(const f of this.fishGroup.children){const a=t*.5+f.userData.phase;f.position.x=f.userData.x+Math.sin(a)*3;f.position.z=f.userData.z+Math.cos(a)*3;oceanPhysics.sampleOceanSurface(f.position.x,f.position.z,t,this.surfaceSample);f.position.y=this.surfaceSample.height-.25+Math.max(0,Math.sin(a*3))*.9;f.rotation.y=a+Math.PI/2;}this.shark.visible=shark.state!=='away';if(this.shark.visible){const a=b.angle+.8;this.shark.position.set(b.x+Math.sin(a)*shark.distance,.1,b.z+Math.cos(a)*shark.distance);oceanPhysics.sampleOceanSurface(this.shark.position.x,this.shark.position.z,t,this.surfaceSample);this.shark.position.y=this.surfaceSample.height+.1;this.shark.lookAt(b.x,this.shark.position.y,b.z);}this.rain.visible=storm>.2;this.rain.position.set(b.x,0,b.z);if(this.rain.visible){const p=this.rain.geometry.attributes.position;for(let i=0;i<p.count;i++){let y=p.getY(i)-dt*24;if(y<0)y=45;p.setY(i,y);}p.needsUpdate=true;}this.coast.update(dt,t,this.camera);this.ocean.renderReflection(this.camera,this.sky);this.renderer.render(this.scene,this.camera);this.ocean.stats.mainCalls=this.renderer.info.render.calls;this.ocean.stats.mainTriangles=this.renderer.info.render.triangles;}
}
